# ============================================================
# HELPER FUNCTIONS
# ============================================================

def hidden_1d_function(x):
    """
    Hidden objective used in the 1D teaching example.
    Students do not need to know this equation.
    """

    x = np.asarray(x)

    return (
        2.0 * np.sin(x)
        + 0.25 * x
        + 0.5 * np.cos(2 * x)
    )


# ============================================================
# PHARMACEUTICAL VIRTUAL REACTOR
# ============================================================

def run_pharma_experiment(
    X, noise =True,
    random_state=None
):

    X = np.atleast_2d(X)

    temperature = X[:, 0]
    residence_time = X[:, 1]
    equivalence = X[:, 2]

    # Synthetic product yield
    yield_true = (
        55
        + 34 * np.exp(
            -((temperature - 103) / 20) ** 2
            -((residence_time - 13) / 6) ** 2
            -((equivalence - 1.45) / 0.35) ** 2
        )
        + 6 * np.exp(
            -((temperature - 116) / 13) ** 2
            -((residence_time - 8) / 5) ** 2
        )
    )

    # Synthetic impurity
    impurity_true = (
        0.6
        + 0.018 * (temperature - 80)
        + 0.035 * np.maximum(
            residence_time - 10,
            0
        )
        + 1.6 * (equivalence - 1.35) ** 2
        + 1.8 * np.exp(
            -((temperature - 118) / 10) ** 2
        )
    )

    impurity_true = np.maximum(
        impurity_true,
        0.05
    )

    if noise:

        rng = np.random.default_rng(
            random_state
        )

        yield_true = (
            yield_true
            + rng.normal(
                0,
                0.8,
                size=len(X)
            )
        )

        impurity_true = (
            impurity_true
            + rng.normal(
                0,
                0.08,
                size=len(X)
            )
        )

    return (
        yield_true,
        impurity_true
    )


# ============================================================
# CREATE GP KERNEL
# ============================================================

def create_kernel(
    kernel_name,
    length_scale,
    noise
):

    if kernel_name == "RBF":

        base_kernel = RBF(
            length_scale=length_scale
        )

    else:

        base_kernel = Matern(
            length_scale=length_scale,
            nu=2.5
        )

    kernel = (
        ConstantKernel(1.0)
        * base_kernel
        + WhiteKernel(
            noise_level=noise
        )
    )

    return kernel


# ============================================================
# EXPECTED IMPROVEMENT
# ============================================================

def expected_improvement(
    mean,
    std,
    best, xi =0.01
):

    std = np.maximum(
        std,
        1e-12
    )

    improvement = (
        mean
        - best
        - xi
    )

    Z = improvement / std

    EI = (
        improvement * norm.cdf(Z)
        + std * norm.pdf(Z)
    )

    return np.maximum(
        EI,
        0
    )


# ============================================================
# PARETO FRONT
# ============================================================

def find_pareto_front(
    yield_values,
    impurity_values
):

    n = len(yield_values)

    pareto = np.ones(
        n, dtype =bool
    )

    for i in range(n):

        for j in range(n):

            if i == j:
                continue

            better_or_equal = (
                yield_values[j] >= yield_values[i]
                and
                impurity_values[j] <= impurity_values[i]
            )

            strictly_better = (
                yield_values[j] > yield_values[i]
                or
                impurity_values[j] < impurity_values[i]
            )

            if (
                better_or_equal
                and
                strictly_better
            ):

                pareto[i] = False
                break

    return pareto


# ============================================================
# INITIAL PHARMA DATA
# ============================================================

def create_initial_pharma_data():

    bounds = np.array([
        [60, 120],
        [2, 20],
        [1.0, 2.0]
    ])

    sampler = qmc.LatinHypercube(
        d=3,
        seed=42
    )

    X_unit = sampler.random(
        n=12
    )

    X = qmc.scale(
        X_unit,
        bounds[:, 0],
        bounds[:, 1]
    )

    y, impurity = run_pharma_experiment(
        X, noise =True,
        random_state=42
    )

    data = pd.DataFrame(
        X, columns =[
            "Temperature",
            "Residence_Time",
            "Equivalence"
        ]
    )

    data["Yield"] = y
    data["Impurity"] = impurity

    data["Experiment"] = np.arange(
        1,
        13
    )

    return data


